import type { ImageSlot } from './media'

/**
 * Coaching team. Each coach gets a profile card.
 * TODO(owner): roles, specialties, bios, certifications, photos and Instagram handles.
 */
export interface Coach {
  slug: string
  name: string
  role: string
  specialties: string[]
  bio: string
  certifications: string[]
  instagram?: string
  /** Which locations they coach at (slugs) */
  locations: string[]
  photo: ImageSlot
}

const portrait = (slug: string, name: string, hasPhoto: boolean): ImageSlot => ({
  kind: 'image',
  // Generated by `npm run media` from the 'coach-<slug>' entry in scripts/media.config.mjs
  src: hasPhoto ? `media/coach-${slug}` : null,
  alt: `${name}, coach at Stoik Gym`,
  focus: '50% 30%',
  label: `Portrait · ${name} · 4:5 · dark backdrop`,
  aspect: '4 / 5',
})

const coach = (slug: string, name: string, hasPhoto = false): Coach => ({
  slug,
  name,
  role: 'Coach',
  specialties: [],
  bio: '',
  certifications: [],
  locations: ['roseville'],
  photo: portrait(slug, name, hasPhoto),
})

export const coaches: Coach[] = [
  coach('cinthia-beltran', 'Cinthia Beltran'),
  coach('michael-lopez', 'Michael Lopez', true),
  coach('mel-renee', 'Mel Renee', true),
  coach('stephanie-pleasas', 'Stephanie Pleasas'),
  coach('logan-frushour', 'Logan Frushour'),
  coach('tyler-brey', 'Tyler Brey', true),
]
